CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, phone VARCHAR(11) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL DEFAULT '', password_hash VARCHAR(255) NOT NULL DEFAULT '', role ENUM('student','owner','admin') NOT NULL DEFAULT 'student', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS courses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(100) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, description TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'draft', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT chk_courses_status CHECK (status IN ('draft','published')));
CREATE TABLE IF NOT EXISTS lessons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, course_id BIGINT UNSIGNED NOT NULL, title VARCHAR(255) NOT NULL, content TEXT NOT NULL, position INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_lessons_course_position UNIQUE (course_id,position), CONSTRAINT chk_lessons_position CHECK (position>0), FOREIGN KEY (course_id) REFERENCES courses(id));
CREATE TABLE IF NOT EXISTS lesson_progress (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, lesson_id BIGINT UNSIGNED NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'started', completed_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_lesson_progress_user_lesson UNIQUE (user_id,lesson_id), INDEX idx_lesson_progress_lesson (lesson_id), CONSTRAINT chk_lesson_progress_status CHECK (status IN ('started','completed')), CONSTRAINT chk_lesson_progress_completed CHECK ((status='started' AND completed_at IS NULL) OR (status='completed' AND completed_at IS NOT NULL)), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (lesson_id) REFERENCES lessons(id));
CREATE TABLE IF NOT EXISTS activities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, kind VARCHAR(80) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_activities_user_created (user_id,created_at), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS leads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(255) NULL, phone VARCHAR(20) NULL, source VARCHAR(100) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'new', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_leads_status_created (status,created_at), CONSTRAINT chk_leads_name CHECK (CHAR_LENGTH(TRIM(name))>0), CONSTRAINT chk_leads_source CHECK (CHAR_LENGTH(TRIM(source))>0), CONSTRAINT chk_leads_status CHECK (status IN ('new','contacted','qualified','closed')), CONSTRAINT chk_leads_contact CHECK ((email IS NOT NULL AND CHAR_LENGTH(TRIM(email))>0) OR (phone IS NOT NULL AND CHAR_LENGTH(TRIM(phone))>0)));
CREATE TABLE IF NOT EXISTS otp_codes (phone VARCHAR(11) PRIMARY KEY, otp_hash VARCHAR(255) NOT NULL, expires_at BIGINT NOT NULL, used_at BIGINT NULL, attempts INT NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, CONSTRAINT chk_otp_attempts CHECK (attempts BETWEEN 0 AND 5), CONSTRAINT chk_otp_expiry CHECK (expires_at>created_at), CONSTRAINT chk_otp_used_at CHECK (used_at IS NULL OR (used_at>=created_at AND used_at<=expires_at)));
CREATE TABLE IF NOT EXISTS otp_requests (phone VARCHAR(11) PRIMARY KEY, window_start BIGINT NOT NULL, request_count INT NOT NULL, last_requested BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS subscriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, plan VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', starts_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, INDEX idx_subscriptions_user (user_id,status,expires_at), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS community_posts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, body TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_posts_created (created_at), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS community_replies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, post_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (post_id) REFERENCES community_posts(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS contact_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL, message TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS enrollments (user_id BIGINT UNSIGNED NOT NULL, course_slug VARCHAR(100) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (user_id,course_slug), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, catalog_index INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_project (user_id,catalog_index), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS nova_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, question TEXT NOT NULL, answer TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_nova_messages_user (user_id,id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS nova_usage (user_id BIGINT UNSIGNED NOT NULL, month VARCHAR(7) NOT NULL, used INT NOT NULL DEFAULT 0, PRIMARY KEY (user_id,month), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS challenge_progress (user_id BIGINT UNSIGNED NOT NULL, challenge_index INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'started', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (user_id,challenge_index), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, subject VARCHAR(180) NOT NULL, priority VARCHAR(20) NOT NULL DEFAULT 'متوسط', status VARCHAR(20) NOT NULL DEFAULT 'open', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_tickets_user (user_id,status), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS ticket_replies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ticket_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (ticket_id) REFERENCES tickets(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS announcements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, body TEXT NOT NULL, audience VARCHAR(20) NOT NULL DEFAULT 'all', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS content_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, kind VARCHAR(40) NOT NULL DEFAULT 'مقاله', status VARCHAR(40) NOT NULL DEFAULT 'پیش‌نویس', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS post_reactions (post_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, kind VARCHAR(20) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (post_id,user_id,kind), FOREIGN KEY (post_id) REFERENCES community_posts(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS user_follows (follower_id BIGINT UNSIGNED NOT NULL, followed_id BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (follower_id,followed_id), FOREIGN KEY (follower_id) REFERENCES users(id), FOREIGN KEY (followed_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS settings (skey VARCHAR(80) PRIMARY KEY, svalue TEXT NOT NULL);
